    'Basis-URL' => 'Base URL',
    '(voor agent-instructies)' => '(for agent instructions)',
    'Pad naar ping' => 'Path to ping',
    'sec' => 'sec',
    'bv. 256M' => 'e.g. 256M',
    'bv. 120' => 'e.g. 120',
    'display_errors (PHP-fouten op het scherm tonen)' => 'display_errors (show PHP errors on screen)',
    'Deze PHP-waarden past RzMon zelf toe (via <code>ini_set</code>). Leeg = waarde uit php.ini. Zet display_errors alleen aan bij het debuggen.' => 'RzMon applies these PHP values itself (via <code>ini_set</code>). Empty = value from php.ini. Only turn display_errors on while debugging.',
    'Opslaan' => 'Save',
    '4. Beheerder aanmaken' => '4. Create administrator',
    'Aanmaken &amp; naar dashboard' => 'Create &amp; go to dashboard',
    'De checks draaien elke minuut via cron. Plaats deze regel op de server (als root):' => 'The checks run every minute via cron. Put this line on the server (as root):',
    'Kopieer' => 'Copy',
    'Sluiten' => 'Close',
