    'geen' => 'none',
    'Draait als gebruiker' => 'Runs as user',
    'bv. ik kijk ernaar' => 'e.g. I am looking into it',
    'Storing bevestigen – RzMon' => 'Acknowledge outage – RzMon',
    'Opmerking' => 'Comment',
    '(optioneel)' => '(optional)',
    '✔ Bevestigen' => '✔ Acknowledge',
    'Na bevestigen krijg je voor deze storing geen meldingen meer. Is het weer goed en gaat het later opnieuw mis, dan krijg je wel weer een melding.' => 'After acknowledging you get no more notifications for this outage. If it recovers and fails again later, you will get a notification again.',
    '✔ Bevestigd. Je krijgt voor deze storing geen meldingen meer.' => '✔ Acknowledged. You will get no more notifications for this outage.',
    'Al bevestigd door {who} op {time}' => 'Already acknowledged by {who} on {time}',
    'Al bevestigd op {time}' => 'Already acknowledged on {time}',
    'Deze link werkt niet (meer). Waarschijnlijk is de storing al opgelost: een bevestig-link geldt alleen zolang de storing waarvoor hij is verstuurd nog bezig is.' => 'This link no longer works. The outage has probably been resolved already: an acknowledge link is only valid while the outage it was sent for is still ongoing.',
    'config.php handmatig plaatsen' => 'Place config.php manually',
    'De webserver mag <code>{path}</code> niet schrijven. Maak het bestand zelf aan met deze inhoud en herlaad daarna deze pagina:' => 'The web server may not write <code>{path}</code>. Create the file yourself with this content and then reload this page:',
    'Of geef de webserver tijdelijk schrijfrechten en sla opnieuw op:' => 'Or give the web server write permission temporarily and save again:',
    'Opgeslagen' => 'Saved',
    'Verbonden met {version}. Database "{db}" bestaat.' => 'Connected to {version}. Database "{db}" exists.',
    'Verbonden met {version}. Database "{db}" bestaat nog niet.' => 'Connected to {version}. Database "{db}" does not exist yet.',
    'Klaar' => 'Done',
    'Instellingen opgeslagen' => 'Settings saved',
    'Gekopieerd' => 'Copied',
    'Geselecteerd — druk Ctrl+C' => 'Selected — press Ctrl+C',
    'is precies' => 'is exactly',
    'past op regex' => 'matches regex',
    'Lokaal (deze server)' => 'Local (this server)',
    'Remote met agent' => 'Remote with agent',
    'Remote (alleen netwerk)' => 'Remote (network only)',
    'OK (normaal)' => 'OK (normal)',
    'WARNING (omgekeerd)' => 'WARNING (reversed)',
    'CRITICAL (omgekeerd)' => 'CRITICAL (reversed)',
    'De twee wachtwoorden zijn niet gelijk' => 'The two passwords do not match',
    'Je wachtwoord is gewijzigd.' => 'Your password has been changed.',
    'Log nu in met je nieuwe wachtwoord.' => 'Now sign in with your new password.',
    'IDS aangezet' => 'IDS enabled',
    'IDS uitgezet' => 'IDS disabled',
    'IDS: leren (alleen melden)' => 'IDS: learning (report only)',
    'IDS: blokkeren aanzetten' => 'IDS: enable blocking',
    'RzMon gaat dan echt IP-adressen blokkeren op je servers (eigen nftables-tabel van de agent), bij brute force en als jij op ⛔ klikt. Je LAN, RzMon zelf en de lijst <i>Nooit blokkeren</i> worden nooit automatisch geblokkeerd; op TrueNAS wordt alleen gedetecteerd.' => 'RzMon will then actually block IP addresses on your servers (the agent\'s own nftables table), on brute force and when you click ⛔. Your LAN, RzMon itself and the <i>Never block</i> list are never blocked automatically; on TrueNAS it only detects.',
    'Op een server zelf zet je blokkeren altijd uit met <code>IDS_BLOCK=0</code> in de instellingen van de agent. Doe het eerste gebruik bij voorkeur terwijl je ook via de console kunt inloggen. Deze wijziging komt in het logboek.' => 'On a server itself you can always turn blocking off with <code>IDS_BLOCK=0</code> in the agent\'s settings. Preferably try it for the first time while you can also sign in via the console. This change is recorded in the log.',
    'Blokkeren aanzetten' => 'Enable blocking',
    'IDS: blokkeren staat aan' => 'IDS: blocking is on',
    'alle agents' => 'all agents',
    'mislukte pogingen' => 'failed attempts',
    'Deze blokkade opheffen?' => 'Remove this block?',
    'Gedeblokkeerd; de agent past het binnen een minuut aan' => 'Unblocked; the agent will apply it within a minute',
    'Basismeting opnieuw doen? Wat er nu op de server staat wordt als normaal vastgelegd; tot het einde van de basismeting worden afwijkingen niet gemeld.' => 'Redo the baseline? What is on the server now will be recorded as normal; deviations are not reported until the baseline is complete.',
