    'IDS staat uit: de agents verzamelen niets en er wordt niets geblokkeerd.' => 'IDS is off: the agents collect nothing and nothing is blocked.',
    '<b class="warn-txt">Blokkeren:</b> brute force wordt gemeld <b>en</b> geblokkeerd; met ⛔ blokkeer je zelf een IP.' => '<b class="warn-txt">Blocking:</b> brute force is reported <b>and</b> blocked; use ⛔ to block an IP yourself.',
