    'Privacy-wachtwoord' => 'Privacy password',
    'Test SNMP' => 'Test SNMP',
    'RzMon leest het apparaat zelf uit (UDP-poort 161): zet SNMP aan op het apparaat en geef het IP-adres van RzMon toegang. Daarna kies je bij de server via <b>📡 SNMP-checks</b> wat je wilt bewaken. De community en wachtwoorden worden niet teruggestuurd naar de browser.' => 'RzMon reads the device itself (UDP port 161): enable SNMP on the device and give RzMon\'s IP address access. Then choose what to monitor via <b>📡 SNMP checks</b> on the server. The community and passwords are never sent back to the browser.',
    'Bezig…' => 'Working…',
    '(geen naam)' => '(no name)',
