    'kies uit de lijst' => 'choose from the list',
    'aan sinds {d}' => 'up for {d}',
    'Vink aan wat je wilt bewaken. De drempels kun je daarna per check aanpassen (✎). Iets anders nodig? Gebruik <b>＋ Eigen OID</b>.' => 'Tick what you want to monitor. You can then adjust the thresholds per check (✎). Need something else? Use <b>＋ Custom OID</b>.',
