    '1 extra pad' => '1 extra path',
    '{n} extra paden' => '{n} extra paths',
    'alleen de algemene lijst' => 'only the general list',
    'Na bevestigen krijg je voor deze storing <b>geen meldingen meer</b>: geen herhalingen, en ook niet als hij erger wordt. Zodra de check weer OK is vervalt de bevestiging; gaat het later opnieuw mis, dan krijg je gewoon weer een melding.' => 'After acknowledging you get <b>no more notifications</b> for this outage: no repeats, and none if it gets worse. As soon as the check is OK again the acknowledgement expires; if it goes wrong again later, you will get a notification as usual.',
    'bv. schijf wordt morgen vervangen' => 'e.g. disk will be replaced tomorrow',
    '{n} storing(en) bevestigd' => '{n} outage(s) acknowledged',
    'Storing bevestigd' => 'Outage acknowledged',
    '1 uur' => '1 hour',
    '1 week' => '1 week',
    'Checks blijven draaien en je ziet de status gewoon, maar er gaan <b>geen meldingen</b> uit (Pushover en webhook). Is er na afloop nog iets mis, dan krijg je alsnog een melding.' => 'Checks keep running and you still see the status, but <b>no notifications</b> are sent (Pushover and webhook). If something is still wrong afterwards, you will get a notification then.',
