    'Stille uren' => 'Quiet hours',
    'Diepere controle' => 'Deeper check',
    'Niet alleen "aan", maar ook: luistert hij op zijn poorten, antwoordt hij (HTTP, database, SSH, mail, DNS…), hoe vaak is hij herstart en staan er fouten in het log.' => 'Not just "running", but also: is it listening on its ports, does it respond (HTTP, database, SSH, mail, DNS…), how often has it restarted and are there errors in the log.',
    'Eigen poort(en) of socket' => 'Custom port(s) or socket',
    'bv. 8080, 127.0.0.1:9000 of /run/php-fpm/www.sock' => 'e.g. 8080, 127.0.0.1:9000 or /run/php-fpm/www.sock',
    'Voor als de agent de poort zelf niet vindt (container, socket, andere procesnaam). Wordt altijd getest, en de test van de dienst (HTTP, SSH…) gebruikt deze poort.' => 'For when the agent cannot find the port itself (container, socket, different process name). Always tested, and the service test (HTTP, SSH…) uses this port.',
