    'De agent voert de test uit op de server zelf, dus <code>localhost</code> werkt ook. Nieuwe tests worden binnen 10 minuten opgepikt.' => 'The agent runs the test on the server itself, so <code>localhost</code> works too. New tests are picked up within 10 minutes.',
    'Certificaat controleren' => 'Verify certificate',
