    'Alle ernst' => 'All severities',
    'Vanaf medium' => 'Medium and up',
    'Vanaf high' => 'High and up',
    'Alleen critical' => 'Critical only',
    'De agents (1.47.0 of nieuwer) sturen hun softwarelijst mee; voor de RzMon-server leest RzMon hem zelf. RzMon zoekt daar de bekende kwetsbaarheden (CVE\'s) bij op <b>OSV.dev</b>, met de adviezen van de distributie zelf, plus <i>actief misbruikt</i> (CISA) en de kans op misbruik (EPSS). Naar OSV.dev gaan alleen pakketnamen, versies en de distributie, geen servernamen of IP-adressen. Ondersteund: Debian, Ubuntu, Rocky Linux, AlmaLinux (en RHEL/CentOS via AlmaLinux) en Alpine.' => 'The agents (1.47.0 or newer) send their software list; for the RzMon server, RzMon reads it itself. RzMon looks up the known vulnerabilities (CVEs) on <b>OSV.dev</b>, using the distribution\'s own advisories, plus <i>actively exploited</i> (CISA) and the probability of exploitation (EPSS). Only package names, versions and the distribution are sent to OSV.dev, no server names or IP addresses. Supported: Debian, Ubuntu, Rocky Linux, AlmaLinux (and RHEL/CentOS via AlmaLinux) and Alpine.',
    '<b>Kwetsbaarheden aan</b> (tabblad 🐞 Kwetsbaarheden)' => '<b>Vulnerabilities on</b> (🐞 Vulnerabilities tab)',
    'Dagelijks scannen om' => 'Scan daily at',
    'Tonen vanaf' => 'Show from',
    'alles' => 'everything',
    'Niet scannen:' => 'Do not scan:',
    'Nodig: uitgaand HTTPS naar <code>api.osv.dev</code>, <code>www.cisa.gov</code>, <code>api.first.org</code> en <code>services.nvd.nist.gov</code>. Een ℹ️ info-melding bij een nieuwe critical of actief misbruikte kwetsbaarheid volgt de rij Info bij 🔔 Meldingen. Bijwerken via de agent kan als commando\'s als root aan staan voor die server; anders krijg je het commando om zelf uit te voeren.' => 'Required: outgoing HTTPS to <code>api.osv.dev</code>, <code>www.cisa.gov</code>, <code>api.first.org</code> and <code>services.nvd.nist.gov</code>. An ℹ️ info notification for a new critical or actively exploited vulnerability follows the Info row under 🔔 Notifications. Updating via the agent works when commands as root are on for that server; otherwise you get the command to run yourself.',
    'Kwetsbaarheden lezen' => 'Read vulnerabilities',
