    'gestart {t}' => 'started {t}',
    'Wachten op de agent: hij pakt de opdracht op bij zijn volgende rapport.' => 'Waiting for the agent: it picks up the job with its next report.',
    'Bijgewerkt: {p}' => 'Updated: {p}',
    'Opnieuw gescand: de lijst met kwetsbaarheden is bijgewerkt.' => 'Rescanned: the list of vulnerabilities has been updated.',
    'RzMon scant opnieuw zodra de agent de nieuwe softwarelijst stuurt (meestal binnen een paar minuten).' => 'RzMon rescans as soon as the agent sends the new software list (usually within a few minutes).',
    'Deze agent meldt geen tussenstand. Werk hem bij naar {v} voor een voortgangsbalk.' => 'This agent does not report progress. Update it to {v} for a progress bar.',
    'De update geeft al {n} minuten geen teken van leven (afgebroken?). Kijk in het logboek; RzMon zelf werkt gewoon door.' => 'The update has shown no sign of life for {n} minutes (aborted?). Check the log; RzMon itself keeps running.',
    'Controleer op de server:' => 'Check on the server:',
    'en' => 'and',
    'server' => 'server',
    'Geweigerd' => 'Refused',
    'onversleuteld bericht, maar versleuteling is verplicht voor deze server' => 'unencrypted message, but encryption is required for this server',
    'Versleuteling van de agents' => 'Agent encryption',
    'Met een sleutel versturen de agents (1.49.0 of nieuwer) hun rapporten <b>versleuteld</b> (AES-256 met een handtekening), en komt het antwoord van RzMon versleuteld terug. Dat komt bovenop HTTPS en helpt vooral als agents via HTTP of een proxy verbinden. Een bericht met een verkeerde sleutel of handtekening, of dat ouder is dan 5 minuten, wordt geweigerd en geeft een ⚠️-melding.' => 'With a key, the agents (1.49.0 or newer) send their reports <b>encrypted</b> (AES-256 with a signature), and RzMon\'s reply comes back encrypted. This comes on top of HTTPS and mainly helps when agents connect over HTTP or through a proxy. A message with a wrong key or signature, or older than 5 minutes, is refused and raises a ⚠️ alert.',
    'Versleutelen' => 'Encrypt',
    'Sleutel' => 'Key',
    '(64 tekens; de agents krijgen hem vanzelf bij hun volgende rapport)' => '(64 characters; the agents receive it automatically with their next report)',
    'nog geen sleutel' => 'no key yet',
    'Tonen' => 'Show',
    'Kopiëren' => 'Copy',
    'Sleutel genereren' => 'Generate key',
    'Per server kies je in de <b>Agent Manager</b> (of hieronder) een eigen instelling. <i>Verplicht</i> weigert onversleutelde berichten: zet dat pas aan als 🔒 bij alle servers staat. Agents die nog geen sleutel hebben, krijgen hem bij een onversleuteld rapport; gebruik daarvoor bij voorkeur HTTPS, of geef hem mee met <code>--key</code> bij het installeren.' => 'Per server you choose your own setting in the <b>Agent Manager</b> (or below). <i>Required</i> refuses unencrypted messages: only turn it on once 🔒 shows for every server. Agents without a key receive it with an unencrypted report; preferably use HTTPS for that, or pass it with <code>--key</code> when installing.',
    'Blokkades' => 'Blocks',
    'Een geblokkeerd IP-adres of netwerk krijgt nergens meer toegang tot RzMon: niet de webpagina, niet het inloggen, niet de API en geen agents. Jezelf en de RzMon-server kun je niet blokkeren. Toch buitengesloten? Op de server: <code>sudo php install/install.php --unblock-all</code>' => 'A blocked IP address or network gets no access to RzMon at all: not the web page, not the login, not the API and no agents. You cannot block yourself or the RzMon server. Locked out anyway? On the server: <code>sudo php install/install.php --unblock-all</code>',
    'bv. 203.0.113.7 of 203.0.113.0/24' => 'e.g. 203.0.113.7 or 203.0.113.0/24',
    'reden (optioneel)' => 'reason (optional)',
    'geen API-sleutel meegestuurd' => 'no API key sent',
    'onbekende API-sleutel' => 'unknown API key',
    'verlopen API-sleutel' => 'expired API key',
    'API-sleutel gebruikt vanaf een adres dat niet mag' => 'API key used from an address that is not allowed',
    'de vorige blijft nog 24 uur geldig' => 'the previous one stays valid for 24 hours',
    'versleuteld bericht is onvolledig' => 'encrypted message is incomplete',
    'versleuteld bericht is te oud of komt uit de toekomst (klopt de klok van de server?)' => 'encrypted message is too old or from the future (is the server clock correct?)',
    'verkeerde sleutel of ongeldige handtekening' => 'wrong key or invalid signature',
    'versleuteld bericht, maar RzMon heeft nog geen sleutel' => 'encrypted message, but RzMon has no key yet',
    'dit bericht kwam al eens binnen (opnieuw afgespeeld?)' => 'this message was already received (replayed?)',
    'versleuteld bericht is niet uit te pakken' => 'encrypted message cannot be decrypted',
    'Geen geldig IP-adres of netwerk: {n}' => 'Not a valid IP address or network: {n}',
    'Daarmee blokkeer je jezelf ({ip}); dat kan niet' => 'That would block yourself ({ip}); not allowed',
