    'Zo ziet een melding "{label}" eruit. Als je dit ziet, werkt dit kanaal.' => 'This is what a "{label}" notification looks like. If you see this, this channel works.',
    'Systeeminfo' => 'System info',
    'Meldingen van RzMon zelf (geen checks): per melding waar hij heen gaat. Tijdens <b>stille uren</b> gaat er niets naar buiten, maar komt hij wel op de meldingenpagina. Pushover: <i>stil</i> (zonder geluid) of <i>normaal</i>. Met 🧪 stuur je een voorbeeld naar de aangevinkte kanalen. Infomeldingen van checks stel je in bij de rij <i>Info (checks)</i> hierboven, of per check.' => 'Notifications from RzMon itself (not checks): per notification where it goes. During <b>quiet hours</b> nothing goes out, but it still appears on the alerts page. Pushover: <i>silent</i> (no sound) or <i>normal</i>. 🧪 sends an example to the ticked channels. Info notifications of checks are set in the <i>Info (checks)</i> row above, or per check.',
