    'bij te werken met ⬆' => 'can be updated with ⬆',
    'niets bij te werken' => 'nothing to update',
    'geen (CISA KEV)' => 'none (CISA KEV)',
    'Volgende scan' => 'Next scan',
    'over {t}' => 'in {t}',
    'scan mislukt (zie boven)' => 'scan failed (see above)',
    'Inloggen via http staat uit: je wachtwoord zou leesbaar over het netwerk gaan.' => 'Logging in over http is turned off: your password would travel across the network in plain text.',
    'Open {url}' => 'Open {url}',
    'Van buiten je interne netwerken is tweestapsverificatie (2FA) verplicht. Stel eerst 2FA in vanaf je thuisnetwerk (Mijn account).' => 'Two-factor authentication (2FA) is required from outside your internal networks. Set up 2FA from your home network first (My account).',
    'Beheer via https' => 'Admin over https',
    'alleen via https' => 'https only',
    '1 dag (testfase tot {d})' => '1 day (test phase until {d})',
    '1 jaar' => '1 year',
    'geen beheeradres ingesteld: de beheerpagina is via http bereikbaar' => 'no admin address set: the admin page can be reached over http',
    'de beheerpagina is ook via http bereikbaar' => 'the admin page can also be reached over http',
    'verloopt over {n} dagen ({d})' => 'expires in {n} days ({d})',
    'geldig tot {d} ({issuer})' => 'valid until {d} ({issuer})',
    'Lokale DNS-rewrite' => 'Local DNS rewrite',
    '{host} is vanaf de RzMon-server niet te vinden' => '{host} cannot be resolved from the RzMon server',
    '{host} wijst intern naar {ip}' => '{host} points internally to {ip}',
    '{host} wijst naar {ip} (openbaar): zet een DNS-rewrite naar het LAN-IP van je proxy' => '{host} points to {ip} (public): add a DNS rewrite to the LAN IP of your proxy',
    'Reverse proxy' => 'Reverse proxy',
    'verkeer via {ip}, maar dat staat niet bij Vertrouwde proxy\'s: die bezoekers gelden als extern' => 'traffic via {ip}, but it is not in Trusted proxies: those visitors count as external',
    'je proxy meldt geen https (X-Forwarded-Proto ontbreekt): de sessiecookie is dan niet beveiligd' => 'your proxy does not report https (X-Forwarded-Proto is missing): the session cookie is then not secured',
    'vertrouwd: {ips}' => 'trusted: {ips}',
    '2FA van buiten' => '2FA from outside',
    'niet verplicht: van buiten is een wachtwoord genoeg' => 'not required: from outside a password is enough',
    'verplicht · zonder 2FA alleen thuis: {names}' => 'required · without 2FA only at home: {names}',
    'verplicht · alle gebruikers hebben 2FA' => 'required · all users have 2FA',
    'Beheeradres: gebruik https:// met een naam, bv. https://rzmon.jouwdomein.nl' => 'Admin address: use https:// with a name, e.g. https://rzmon.yourdomain.com',
    'Vul eerst het beheeradres in' => 'Enter the admin address first',
    'Open RzMon eerst via {url} en zet het daar aan. Zo weet je zeker dat het werkt voordat http dicht gaat.' => 'Open RzMon via {url} first and turn it on there. That way you know it works before http is closed.',
    'Je proxy meldt geen https (X-Forwarded-Proto ontbreekt).' => 'Your proxy does not report https (X-Forwarded-Proto is missing).',
    'Je komt via een proxy die niet bij Vertrouwde proxy\'s staat.' => 'You are coming through a proxy that is not in Trusted proxies.',
    'Niet aangezet: {p}. RzMon controleert het certificaat zelf; kan de RzMon-server {url} niet bereiken, zet de DNS-rewrite dan ook voor de RzMon-server (of een regel in /etc/hosts).' => 'Not turned on: {p}. RzMon checks the certificate itself; if the RzMon server cannot reach {url}, add the DNS rewrite for the RzMon server too (or a line in /etc/hosts).',
    'Zet dit aan terwijl je RzMon via https open hebt; anders sluit je jezelf nu buiten' => 'Turn this on while you have RzMon open over https; otherwise you lock yourself out right now',
    'Je zit nu buiten je interne netwerken en je eigen account heeft nog geen 2FA: stel eerst 2FA in (Mijn account)' => 'You are outside your internal networks and your own account has no 2FA yet: set up 2FA first (My account)',
    'Van buiten je interne netwerken kun je je eigen 2FA niet uitzetten' => 'You cannot turn off your own 2FA from outside your internal networks',
    'Deze verbinding is niet beveiligd: je wachtwoord en sessie zijn leesbaar op het netwerk.' => 'This connection is not secure: your password and session can be read on the network.',
    'Open je RzMon via http, dan kan iemand op het netwerk je wachtwoord, je sessie en de pagina zelf (bv. een installatiecommando) zien of veranderen. Met een <b>beheeradres</b> via je reverse proxy (bv. SWAG met Let\'s Encrypt) en <i>Beheer alleen via https</i> gaat de webinterface altijd via https. Agents en de REST API blijven gewoon werken: hun berichten zijn al versleuteld of hebben een eigen sleutel.' => 'If you open RzMon over http, someone on the network can see or change your password, your session and the page itself (e.g. an install command). With an <b>admin address</b> via your reverse proxy (e.g. SWAG with Let\'s Encrypt) and <i>Admin over https only</i>, the web interface always uses https. Agents and the REST API keep working: their messages are already encrypted or have their own key.',
    'Beheeradres' => 'Admin address',
    '(https://… via je reverse proxy, bv. https://rzmon.jouwdomein.nl)' => '(https://… via your reverse proxy, e.g. https://rzmon.yourdomain.com)',
    'Afdwingen' => 'Enforce',
    '<b>Beheer alleen via https</b>: http gaat naar het beheeradres, met HSTS' => '<b>Admin over https only</b>: http goes to the admin address, with HSTS',
    '<b>Inloggen via http weigeren</b> (op de inlogpagina via http staat dan een rode balk met de link naar https)' => '<b>Refuse logins over http</b> (the login page over http then shows a red bar with the link to https)',
    '<b>2FA verplicht</b> van buiten je interne netwerken (Toegang → Lokale netwerken)' => '<b>2FA required</b> from outside your internal networks (Access → Local networks)',
    'Zo zet je het op: SWAG en een DNS-rewrite' => 'How to set it up: SWAG and a DNS rewrite',
    '<b>SWAG</b>: maak <code>nginx/proxy-confs/rzmon.subdomain.conf</code> (voorbeeld hieronder) en herstart SWAG. SWAG vraagt het Let\'s Encrypt-certificaat zelf aan en vernieuwt het.' => '<b>SWAG</b>: create <code>nginx/proxy-confs/rzmon.subdomain.conf</code> (example below) and restart SWAG. SWAG requests the Let\'s Encrypt certificate itself and renews it.',
    '<b>Vertrouwde proxy</b>: zet het LAN-IP van SWAG bij Toegang → Geavanceerd → Reverse proxy IP\'s. Dan ziet RzMon het echte IP-adres van je bezoekers en dat ze via https komen.' => '<b>Trusted proxy</b>: add the LAN IP of SWAG under Access → Advanced → Reverse proxy IPs. RzMon then sees the real IP address of your visitors and that they come over https.',
    '<b>DNS-rewrite</b> (AdGuard Home → Filters → DNS-herschrijvingen): <code>rzmon.jouwdomein.nl</code> → het LAN-IP van SWAG. Thuis en onderweg gebruik je dan hetzelfde adres met hetzelfde geldige certificaat. Gebruikt de RzMon-server zelf ook AdGuard als DNS, dan kan hij het certificaat controleren.' => '<b>DNS rewrite</b> (AdGuard Home → Filters → DNS rewrites): <code>rzmon.yourdomain.com</code> → the LAN IP of SWAG. At home and on the road you then use the same address with the same valid certificate. If the RzMon server itself also uses AdGuard for DNS, it can check the certificate.',
    'Open RzMon via het beheeradres, vul het hierboven in en zet <i>Beheer alleen via https</i> aan.' => 'Open RzMon via the admin address, enter it above and turn on <i>Admin over https only</i>.',
    '<b>Nooddeur</b>: https op het IP-adres van RzMon zelf (self-signed, kies "toch doorgaan") blijft vanaf je interne netwerken altijd werken, ook als het certificaat van het beheeradres verlopen is. Buitengesloten? Op de server: <code>sudo php install/install.php --https-off</code>.' => '<b>Emergency door</b>: https on the IP address of RzMon itself (self-signed, choose "proceed anyway") always keeps working from your internal networks, even if the certificate of the admin address has expired. Locked out? On the server: <code>sudo php install/install.php --https-off</code>.',
    '<IP-adres van RzMon>' => '<IP address of RzMon>',
    'RzMon is alleen via https te beheren: open {url}' => 'RzMon can only be managed over https: open {url}',
    'Verkeer via een onbekende proxy: {ip}' => 'Traffic via an unknown proxy: {ip}',
    'Er komen verzoeken met proxy-kopteksten (X-Forwarded-For) binnen van {ip}, maar dat adres staat niet bij Vertrouwde proxy\'s. RzMon behandelt deze bezoekers daarom als extern (2FA verplicht, nooit inloggen zonder wachtwoord). Is dit je reverse proxy (bv. SWAG)? Zet het adres dan bij Instellingen → Toegang → Reverse proxy IP\'s.' => 'Requests with proxy headers (X-Forwarded-For) are coming in from {ip}, but that address is not in Trusted proxies. RzMon therefore treats these visitors as external (2FA required, never logged in without a password). Is this your reverse proxy (e.g. SWAG)? Then add the address under Settings → Access → Reverse proxy IPs.',
    'geen verbinding' => 'no connection',
    'niet vertrouwd of de naam klopt niet' => 'not trusted or the name does not match',
    'geen https-verbinding met {url}: {err}' => 'no https connection to {url}: {err}',
    'het certificaat is niet vertrouwd of de naam klopt niet ({issuer})' => 'the certificate is not trusted or the name does not match ({issuer})',
    'het certificaat is verlopen op {d}' => 'the certificate expired on {d}',
    'Certificaat van RzMon: probleem' => 'RzMon certificate: problem',
    'Kun je RzMon niet meer openen? Gebruik vanaf je thuisnetwerk de nooddeur {door} (self-signed: kies "toch doorgaan").' => 'Can\'t open RzMon anymore? From your home network, use the emergency door {door} (self-signed: choose "proceed anyway").',
    'Certificaat van RzMon weer in orde' => 'RzMon certificate OK again',
    '{url}: geldig tot {d} ({issuer})' => '{url}: valid until {d} ({issuer})',
    'Certificaat verloopt over {n} dagen' => 'Certificate expires in {n} days',
    'Het certificaat van {url} verloopt op {d} ({issuer}). Normaal vernieuwt je reverse proxy (SWAG) het rond 30 dagen van tevoren; kijk in de log van je proxy waarom dat niet lukt.' => 'The certificate of {url} expires on {d} ({issuer}). Normally your reverse proxy (SWAG) renews it about 30 days in advance; check your proxy\'s log to see why that fails.',
    'Van buiten je interne netwerken kan dit alleen met 2FA. Herstel je wachtwoord vanaf je thuisnetwerk.' => 'From outside your internal networks this is only possible with 2FA. Reset your password from your home network.',
    'Je komt via een proxy ({ip}) die niet bij Reverse proxy IP\'s staat: RzMon behandelt je daarom als extern.' => 'You are coming through a proxy ({ip}) that is not in Reverse proxy IPs: RzMon therefore treats you as external.',
    'vertrouwd' => 'trusted',
    'self-signed' => 'self-signed',
