    'Inlogpoging van buiten op een lokaal account' => 'Login attempt from outside on a local account',
    'Mag alleen vanaf je interne netwerken inloggen (Toegang → Lokale netwerken)' => 'May only log in from your internal networks (Access → Local networks)',
    'alleen lokaal' => 'local only',
