    'De agent krijgt het nieuwe adres versleuteld, <b>test het eerst</b> (verbinding, certificaat en zijn eigen sleutel) en gebruikt het pas als alles klopt; anders blijft het oude adres. Het resultaat zie je na één of twee rapporten in de kolom <i>Verbinding</i>.' => 'The agent receives the new address encrypted, <b>tests it first</b> (connection, certificate and its own key) and only uses it when everything checks out; otherwise the old address stays. You see the result after one or two reports in the <i>Connection</i> column.',
