    'config.php zelf plaatsen' => 'Place config.php yourself',
    'De installatiemap is vergrendeld (zo hoort het). Zet deze inhoud als root in {path}:' => 'The installation folder is locked (as it should be). Put this content in {path} as root:',
    'Verbinding testen' => 'Test connection',
    'Opslaan en tabellen installeren' => 'Save and install tables',
    'Tabellen bijwerken' => 'Update tables',
    'Verbinding OK: {v}' => 'Connection OK: {v}',
    'database bestaat nog niet' => 'database does not exist yet',
    'Databaseverbinding opslaan' => 'Save database connection',
    'RzMon gaat hierna de nieuwe database gebruiken en installeert of werkt daar de tabellen bij. De gegevens in de oude database gaan niet vanzelf mee: zet eerst een back-up terug in de nieuwe database als je verhuist.' => 'RzMon will then use the new database and install or update the tables there. The data in the old database does not move along by itself: restore a backup into the new database first if you are moving.',
    'Sjabloon bestaat niet' => 'Template does not exist',
    'Kies een of meer checks' => 'Choose one or more checks',
    'Drempels kun je alleen voor checks van hetzelfde type tegelijk aanpassen' => 'You can only change thresholds together for checks of the same type',
    'Niets om aan te passen' => 'Nothing to change',
    'Sjablonen' => 'Templates',
    'Een sjabloon is een set checks (met drempels, interval en meldregels) die je aan servers koppelt, bv. <i>Linux-server</i> of <i>Website</i>. Pas je het sjabloon aan, dan veranderen de checks op alle gekoppelde servers mee, behalve checks die je op een server zelf hebt aangepast. Koppelen kan hier of bij <i>✎ Server bewerken</i>.' => 'A template is a set of checks (with thresholds, interval and alert rules) that you link to hosts, e.g. <i>Linux server</i> or <i>Website</i>. When you change the template, the checks on all linked hosts change along, except checks you changed on a host yourself. Link here or under <i>✎ Edit host</i>.',
    'Nieuw sjabloon' => 'New template',
    'Sjabloon maken van een server…' => 'Create template from a host…',
    'Alle checks' => 'All checks',
    'Vink checks aan om ze tegelijk aan te passen: interval, drempels, melden, onderhoud, aan of uit, kopiëren naar andere servers of verwijderen. Klik op een naam om die check te bewerken.' => 'Tick checks to change them together: interval, thresholds, alerting, maintenance, on or off, copy to other hosts or delete. Click a name to edit that check.',
    '🔍 Zoek check, doel of server…' => '🔍 Search check, target or host…',
